    ["c62","Standards and Certification Compliance","Whether equipment and installation practice meet applicable standards and compliance can be verified.","Malawi Energy Regulation Act; Lighting Global; IEC 62548-1"],
    ["c63","Alignment with National Energy Priorities","Whether the project is consistent with the National Energy Policy, SE4ALL commitments and Malawi 2063.","Malawi National Energy Policy; Zalengera et al."],
    ["c64","Institutional Coordination and Reporting","Whether MERA, the Department of Energy, councils and environmental authorities coordinate and whether project data enter national reporting.","Malawi Energy Regulation Act; Zalengera et al."]
